package com.icbc.changzhou.ipam;

import com.google.gson.JsonObject;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.sql.*;
import java.util.*;
import org.apache.poi.ss.usermodel.*;
import org.apache.poi.xssf.usermodel.XSSFWorkbook;

/** MAC address regression: free text, snapshots, privacy, exports and V020 upgrade. */
public final class StageThirteenMacAddressSmokeTest {
  private static final String MAC="AA:BB:CC:DD:EE:FF";
  private static final String EDITED_MAC="112233445566";
  public static void main(String[] args)throws Exception{
    Path work=Files.createTempDirectory("ipam-stage13-mac-");Path db=work.resolve("mac.db");migrate(db);seed(db);
    PhaseFourService phase4=new PhaseFourService(db);JsonObject plan=json("branchId","1","outletId","1","productionCidr","108.56.32.0/24");phase4.createPlan(plan,1L);
    assertFreeText();long asset=createAsset(phase4);PhaseThreeService phase3=new PhaseThreeService(db);ManualAssignmentService manual=new ManualAssignmentService(db);
    long approvalPool=pool(db,"OFFICE");long app=phase4.submitApplication(2L,json("branchId","1","outletId","1","assetId",String.valueOf(asset)));phase4.approve(app,approvalPool,"OFFICE","同 MAC 审批",null,null,MAC,1L);long assignment=findAssignment(db,approvalPool);assertText(db,"SELECT mac_address FROM ip_assignment WHERE id="+assignment,MAC,"approval MAC not persisted");
    long manualPool=pool(db,"OFFICE",approvalPool);JsonObject manualBody=json("assetId",String.valueOf(asset),"assetType","NON_TECH","responsibleTechUserId","2","macAddress",MAC);long manualAssignment=((Number)manual.register(manualPool,manualBody,1L).get("id")).longValue();assertText(db,"SELECT mac_address FROM ip_assignment WHERE id="+manualAssignment,MAC,"manual MAC not persisted");if(count(db,"SELECT count(*) FROM ip_assignment WHERE status='ASSIGNED' AND mac_address='"+MAC+"'")!=2)throw new AssertionError("same MAC must be allowed on two active assignments");
    long version=version(db,assignment);Map<String,Object> changed=phase4.updateMac(approvalPool,assignment,version,"112233445566",1L);if(!Boolean.TRUE.equals(changed.get("changed"))||!EDITED_MAC.equals(changed.get("macAddress"))||version(db,assignment)!=version+1)throw new AssertionError("MAC edit did not preserve input or advance version");Map<String,Object> same=phase4.updateMac(approvalPool,assignment,version+1,EDITED_MAC,1L);if(!Boolean.FALSE.equals(same.get("changed"))||count(db,"SELECT count(*) FROM audit_log WHERE action='UPDATE_MAC'")!=1)throw new AssertionError("same MAC must be a no-op without audit");boolean stale=false;try{phase4.updateMac(approvalPool,assignment,version,"00:11:22:33:44:55",1L);}catch(PhaseTwoService.Problem e){stale="ALLOCATION_STALE".equals(e.code);}if(!stale)throw new AssertionError("stale MAC update must be rejected");Map<String,Object> cleared=phase4.updateMac(approvalPool,assignment,version+1,"  ",1L);if(cleared.get("macAddress")!=null)throw new AssertionError("empty MAC must clear");phase4.updateMac(approvalPool,assignment,version+2,MAC,1L);long releaseEvent=((Number)phase3.forceRelease(assignment,1L,"MAC 快照回归","stage13").get("releaseEventId")).longValue();assertText(db,"SELECT mac_address FROM ip_release_event WHERE id="+releaseEvent,MAC,"release MAC snapshot missing");if(poolMac(phase4,approvalPool)!=null)throw new AssertionError("released pool must not expose current MAC");
    long reapp=phase4.submitApplication(2L,json("branchId","1","outletId","1","assetId",String.valueOf(asset)));phase4.approve(reapp,approvalPool,"OFFICE","复用地址",null,null,null,1L);if(poolMac(phase4,approvalPool)!=null)throw new AssertionError("reassigned IP must start with null MAC");
    if(phase4.applicationsForApplicant(null,null,2L).get(0).containsKey("macAddress"))throw new AssertionError("tech application response leaked MAC");if(phase3.myAssignments(2L).get(0).containsKey("macAddress"))throw new AssertionError("tech assignment response leaked MAC");if(!phase3.notifications(2L).isEmpty()&&phase3.notifications(2L).get(0).containsKey("macAddress"))throw new AssertionError("tech notification response leaked MAC");
    Set<String> macOnly=new LinkedHashSet<>();macOnly.add("macAddress");String csv=new String(phase3.exportManualAware("RELEASE","CSV",macOnly,Collections.<String,String>emptyMap(),1L),StandardCharsets.UTF_8);if(!csv.contains("macAddress")||!csv.contains(MAC))throw new AssertionError("selected release CSV MAC missing");Set<String> ipOnly=new LinkedHashSet<>();ipOnly.add("ipAddress");String hidden=new String(phase3.exportManualAware("RELEASE","CSV",ipOnly,Collections.<String,String>emptyMap(),1L),StandardCharsets.UTF_8);if(hidden.contains("macAddress")||hidden.contains(MAC))throw new AssertionError("unselected release CSV MAC leaked");byte[] xlsx=phase3.exportManualAware("ASSIGNMENT","XLSX",macOnly,Collections.<String,String>emptyMap(),1L);try(XSSFWorkbook wb=new XSSFWorkbook(new java.io.ByteArrayInputStream(xlsx))){if(!"macAddress".equals(wb.getSheetAt(0).getRow(0).getCell(0).getStringCellValue()))throw new AssertionError("selected XLSX MAC header missing");}
    Path legacySource=args.length>0?Paths.get(args[0]):work.resolve("v019-fixture.db");if(args.length==0)StageTwelveV019UpgradeSmokeTest.createV019Fixture(legacySource);verifyV020Upgrade(legacySource,work.resolve("v020-upgrade.db"));
    System.out.println("PASS|STAGE13_MAC_FREE_TEXT_SNAPSHOT_PRIVACY_EXPORT_REASSIGN_V020_UPGRADE|"+work);
  }
  private static void assertFreeText(){
    String[] accepted={" aa:bb:cc:dd:ee:ff ","aa-bb-cc-dd-ee-ff","aabbccddeeff","aa:bb-cc:dd:ee:ff","aa:bb:cc:dd:ee","aa:bb:cc:dd:ee:ff:11","aa bb:cc:dd:ee:ff","aa:bb:cc:dd:ee:fg","0011:2233:4455:6677","设备标签 临时值","=自由录入"};
    for(String value:accepted)if(!value.equals(PhaseFourService.normalizeMac(value)))throw new AssertionError("MAC text must be preserved: "+value);
    if(PhaseFourService.normalizeMac(" ")!=null)throw new AssertionError("empty MAC must be null");
    String nul=String.valueOf((char)0),lf=String.valueOf((char)10),cr=String.valueOf((char)13),tab=String.valueOf((char)9);
    String[] bad={nul+MAC,MAC+lf,cr+MAC,MAC+tab,"AA:BB:CC:DD:"+lf+"EE:FF","AA:BB:CC:DD:"+cr+"EE:FF","AA:BB:CC:DD:"+tab+"EE:FF",String.join("",Collections.nCopies(257,"x"))};
    for(String value:bad)assertInvalidMac(value);
  }
  private static void assertInvalidMac(String x){boolean rejected=false;try{PhaseFourService.normalizeMac(x);}catch(PhaseTwoService.Problem e){rejected="MAC_INVALID".equals(e.code);}if(!rejected)throw new AssertionError("invalid MAC accepted: "+x.replace(String.valueOf((char)0),"<NUL>").replace(String.valueOf((char)10),"<LF>").replace(String.valueOf((char)13),"<CR>").replace(String.valueOf((char)9),"<TAB>"));}
  private static void verifyV020Upgrade(Path source,Path target)throws Exception{if(!Files.isRegularFile(source))throw new AssertionError("V020 source database missing: "+source);copyDatabase(source,target);try(Connection c=open(target)){java.lang.reflect.Method apply=databaseMethod("applyManualAssignmentMigration",Connection.class,String.class,String.class,String.class);apply.invoke(database(target),c,"020","manual assignment and gateway adjustment","/db/migration/V020__manual_assignment_and_gateway.sql");}long before=count(target,"SELECT count(*) FROM ip_assignment");long releases=count(target,"SELECT count(*) FROM ip_release_event");migrate(target);if(count(target,"SELECT count(*) FROM schema_history WHERE version='021'")!=1||count(target,"SELECT count(*) FROM schema_history WHERE version='022'")!=1||count(target,"SELECT count(*) FROM ip_assignment")!=before||count(target,"SELECT count(*) FROM ip_release_event")!=releases)throw new AssertionError("V020 to V021 upgrade changed history counts");}
  private static Object database(Path db)throws Exception{Class<?> type=Class.forName("com.icbc.changzhou.ipam.IpamApplication$Database");java.lang.reflect.Constructor<?> ctor=type.getDeclaredConstructor(Path.class);ctor.setAccessible(true);return ctor.newInstance(db);}
  private static java.lang.reflect.Method databaseMethod(String name,Class<?>...types)throws Exception{Class<?> type=Class.forName("com.icbc.changzhou.ipam.IpamApplication$Database");java.lang.reflect.Method m=type.getDeclaredMethod(name,types);m.setAccessible(true);return m;}
  private static void migrate(Path db)throws Exception{databaseMethod("migrate").invoke(database(db));}
  private static void seed(Path db)throws Exception{try(Connection c=open(db);Statement s=c.createStatement()){s.execute("INSERT INTO sys_user(username,password_hash,real_name,role,is_active,must_change_password,is_initial_admin) VALUES('admin13','x','管理员','ADMIN',1,0,1)");s.execute("INSERT INTO branch(code,name,is_active) VALUES('B13','阶段四 MAC 支行',1)");s.execute("INSERT INTO outlet(branch_id,code,name,is_active) VALUES(1,'O13','阶段四 MAC 网点',1)");s.execute("INSERT INTO sys_user(username,password_hash,real_name,role,is_active,must_change_password,is_initial_admin,branch_id,outlet_id) VALUES('tech13','x','科技管理员','TECH_ADMIN',1,0,0,1,1)");}}
  private static long createAsset(PhaseFourService service)throws Exception{JsonObject b=json("assetType","NON_TECH","name","MAC 回归资产","requiresUser","0","requiresResourceCode","0","recommendedRangeType","OFFICE","active","1");return ((Number)service.createAsset(b,1L).get("id")).longValue();}
  private static JsonObject json(String...values){JsonObject x=new JsonObject();for(int i=0;i+1<values.length;i+=2){try{x.addProperty(values[i],Long.valueOf(values[i+1]));}catch(Exception e){x.addProperty(values[i],values[i+1]);}}return x;}
  private static long pool(Path db,String type,long...exclude)throws Exception{Set<Long> skip=new HashSet<>();for(long x:exclude)skip.add(x);try(Connection c=open(db);PreparedStatement p=c.prepareStatement("SELECT p.id FROM ip_address_pool p JOIN ip_range r ON r.id=p.ip_range_id LEFT JOIN ip_assignment d ON d.ip_pool_id=p.id AND d.status='ASSIGNED' WHERE r.range_type=? AND p.ip_address<>r.gateway AND p.is_active=1 AND p.is_reserved=0 AND d.id IS NULL ORDER BY p.id")){p.setString(1,type);try(ResultSet r=p.executeQuery()){while(r.next())if(!skip.contains(r.getLong(1)))return r.getLong(1);}}throw new AssertionError("pool unavailable: "+type);}
  private static long findAssignment(Path db,long pool)throws Exception{try(Connection c=open(db);PreparedStatement p=c.prepareStatement("SELECT id FROM ip_assignment WHERE ip_pool_id=? AND status='ASSIGNED' ORDER BY id DESC LIMIT 1")){p.setLong(1,pool);try(ResultSet r=p.executeQuery()){if(!r.next())throw new AssertionError("assignment missing");return r.getLong(1);}}}
  private static long version(Path db,long id)throws Exception{try(Connection c=open(db);PreparedStatement p=c.prepareStatement("SELECT version FROM ip_assignment WHERE id=?")){p.setLong(1,id);try(ResultSet r=p.executeQuery()){r.next();return r.getLong(1);}}}
  private static String poolMac(PhaseFourService service,long pool)throws Exception{Map<String,Object> first=service.pool(null,null,null,"",1);int pages=(int)Math.ceil(((Number)first.get("total")).doubleValue()/((Number)first.get("pageSize")).doubleValue());for(int page=1;page<=Math.max(1,pages);page++){Map<String,Object> rows=page==1?first:service.pool(null,null,null,"",page);for(Map<String,Object> row:(List<Map<String,Object>>)rows.get("items"))if(((Number)row.get("id")).longValue()==pool)return row.get("macAddress")==null?null:String.valueOf(row.get("macAddress"));}throw new AssertionError("pool row missing");}
  private static void assertText(Path db,String sql,String expected,String message)throws Exception{try(Connection c=open(db);Statement s=c.createStatement();ResultSet r=s.executeQuery(sql)){if(!r.next()||!expected.equals(r.getString(1)))throw new AssertionError(message);}}
  private static long count(Path db,String sql)throws Exception{try(Connection c=open(db);Statement s=c.createStatement();ResultSet r=s.executeQuery(sql)){r.next();return r.getLong(1);}}
  private static void copyDatabase(Path source,Path target)throws Exception{try(Connection c=open(source);PreparedStatement p=c.prepareStatement("VACUUM INTO ?")){p.setString(1,target.toString());p.executeUpdate();}}
  private static Connection open(Path db)throws Exception{Connection c=DriverManager.getConnection("jdbc:sqlite:"+db);try(Statement s=c.createStatement()){s.execute("PRAGMA foreign_keys=ON");s.execute("PRAGMA busy_timeout=5000");}return c;}
}
